import { useCallback, useState, type CSSProperties, type KeyboardEvent } from 'react';
import { useParamGesture } from '../gesture/useParamGesture.ts';
import { clamp, quantize, type Param } from '../param/param.ts';
import { defaultOrigin, fillFrom, type FillOrigin } from './fill.ts';
import { hintAttribute } from './hint.ts';
import { useReserved } from './reserve.ts';
import './controls.css';

/** `live.numbox`: drag it like a fader, or type into it. */
export interface NumberFieldProps {
  param: Param;
  value: number;
  onChange(next: number): void;
  onRelease?(): void;
  disabled?: boolean;
  display?: string;
  label?: string;
  name?: string;
  /** Typing a digit or pressing Enter opens the editor. Never for an enum. */
  editable?: boolean;
  /** The value drawn as a bar behind the text, as Live's own value boxes do. */
  showFill?: boolean;
  /** Where that bar grows from. Defaults to the middle when zero is the middle. */
  origin?: FillOrigin;
  /** In px. Defaults to the parameter's longest reading, so it never resizes. */
  width?: number;
  travel?: number;
  className?: string;
  title?: string;
  /**
   * A sentence for the window's hint strip, on the root as `data-hint`.
   *
   * Left out, the strip falls back to `title`. See [`hint.ts`](./hint.ts).
   */
  hint?: string;
}

const OPENS_EDITOR = /^[-+.0-9]$/;

export function NumberField({
  param,
  value,
  onChange,
  onRelease,
  disabled = false,
  display,
  label,
  name = param.shortName ?? param.name,
  editable = true,
  showFill = true,
  origin = defaultOrigin(param),
  width,
  travel,
  className,
  title,
  hint,
}: NumberFieldProps) {
  const [draft, setDraft] = useState<string | null>(null);
  const reserved = useReserved(param);
  const typeable = editable && param.kind !== 'enum' && param.kind !== 'blob' && !disabled;

  const gesture = useParamGesture({
    param,
    value,
    onChange,
    onRelease,
    disabled,
    axis: 'horizontal',
    travel,
    label: label ?? name,
    display,
  });

  const commit = useCallback(
    (text: string) => {
      setDraft(null);
      const parsed = Number.parseFloat(text);
      if (Number.isNaN(parsed)) return;
      onChange(quantize(param, clamp(param, parsed)));
      onRelease?.();
    },
    [onChange, onRelease, param],
  );

  const onKeyDown = (e: KeyboardEvent<HTMLElement>) => {
    if (typeable && (e.key === 'Enter' || OPENS_EDITOR.test(e.key))) {
      e.preventDefault();
      e.stopPropagation();
      setDraft(e.key === 'Enter' ? '' : e.key);
      return;
    }
    gesture.props.onKeyDown(e);
  };

  return (
    <div
      className={`wdg wdg-number${className ? ` ${className}` : ''}`}
      {...hintAttribute(hint)}
      style={
        {
          ...reserved,
          ...fillFrom(param, origin, gesture.fraction),
          ...(width === undefined ? {} : { '--wdg-number-width': `${width}px` }),
        } as CSSProperties
      }
    >
      {name && <span className="wdg-caption">{name}</span>}
      {draft === null ? (
        <div className="wdg-number-body wdg-body" title={title} {...gesture.props} onKeyDown={onKeyDown}>
          {showFill && <span className="wdg-number-fill" aria-hidden="true" />}
          <span className="wdg-number-text">{gesture.text}</span>
          {showFill && (
            <span className="wdg-number-ink" aria-hidden="true">
              {gesture.text}
            </span>
          )}
        </div>
      ) : (
        <input
          className="wdg-number-body wdg-body wdg-number-input"
          ref={(node) => {
            node?.focus();
          }}
          value={draft}
          aria-label={label ?? name}
          inputMode="decimal"
          onChange={(e) => setDraft(e.currentTarget.value)}
          onBlur={(e) => commit(e.currentTarget.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') commit(e.currentTarget.value);
            else if (e.key === 'Escape') setDraft(null);
            else return;
            e.preventDefault();
          }}
        />
      )}
    </div>
  );
}
